S = load('input.mat');
disp(fieldnames(S));
x = S.x(:); fs = double(S.fs);
fprintf('N=%d fs=%.6g\n', numel(x), fs);
try
  c = S.claims;
  if isstruct(c), disp(c); else, disp(c); end
catch e
  disp(e.message);
end
N = numel(x);
w = hann(N);
X = abs(fft(x .* w, 8*N));
f = (0:numel(X)-1)' * fs / numel(X);
half = f <= fs/2;
P = X(half); f = f(half);
[~, idx] = sort(P, 'descend');
found = false; peaks = [];
for k = 1:numel(idx)
  i = idx(k);
  if ~isempty(peaks) && min(abs(f(i) - peaks)) < 5, continue; end
  if i > 1 && i < numel(P)
    a=P(i-1); b=P(i); cc=P(i+1);
    d = 0.5*(a-cc)/(a-2*b+cc);
  else
    d = 0;
  end
  fp = f(i) + d*diff(f(1:2));
  peaks(end+1) = fp; %#ok
  fprintf('peak %d: f=%.4f Hz mag=%.6g\n', numel(peaks), fp, b);
  if numel(peaks) >= 6, break; end
end
% power in 55-65 Hz band vs total
