try, fprintf('claimed=%.6g tol=%.6g\n', S.claims.freq.value, S.claims.freq.tol); catch, end
x = S.x(:); fs = double(S.fs); N = numel(x);
% Goertzel-style exact check: compare power at exactly 60 vs 50 Hz via long FFT zero-padded
X = abs(fft(x .* hann(N), 64*N));
f = (0:numel(X)-1)' * fs / numel(X);
half = f <= fs/2; P = X(half); f = f(half);
[mp, mi] = max(P);
fprintf('global max f=%.5f Hz (bin spacing %.5f)\n', f(mi), fs/(64*N));
i60 = find(abs(f-60) < 1e-6, 1); i50 = find(abs(f-50) < 1e-6, 1);
fprintf('P(60)=%.4g P(50)=%.4g ratio=%.4g\n', P(i60), P(i50), P(i60)/P(i50));
